//! Kernel identity in the shape Linux exposes through `uname(2)`, `/proc/version`
//! and `/proc/sys/kernel/*`.  `uname` uses the six `struct new_utsname` fields
//! mandated by the Linux ABI; build metadata is generated by the build system.

use alloc::{format, string::String};
use core::sync::atomic::{AtomicU64, Ordering};

use crate::sync::SpinLock;

pub const NAME: &str = "SpaceKernel";
pub const VERSION: &str = "3.0";
pub const DISTRO_NAME: &str = "SpaceOS";
pub const DISTRO_VERSION: &str = "9";
pub const DISTRO_ID: &str = "spaceos9";
pub const DISTRO_PRETTY_NAME: &str = "SpaceOS 9";
pub const DISTRO_HOME_URL: &str = "https://github.com/ViudiraTech/SpaceOS-9";
pub const UTS_SYSNAME: &str = "SpaceKernel";
pub const UTS_DEFAULT_NODENAME: &str = "spaceos9";
pub const UTS_DOMAINNAME: &str = "(none)";
pub const UTS_FIELD_LEN: usize = 65;
const UTS_NAME_LEN: usize = UTS_FIELD_LEN - 1;

#[cfg(target_arch = "x86_64")]
pub const UTS_MACHINE: &str = "x86_64";
#[cfg(target_arch = "aarch64")]
pub const UTS_MACHINE: &str = "aarch64";
#[cfg(target_arch = "riscv64")]
pub const UTS_MACHINE: &str = "riscv64";
#[cfg(not(any(
    target_arch = "x86_64",
    target_arch = "aarch64",
    target_arch = "riscv64"
)))]
pub const UTS_MACHINE: &str = "unknown";

pub const BUILD_NUMBER: &str = match option_env!("SPK_BUILD_NUMBER") {
    Some(value) => value,
    None => "0",
};
pub const BUILD_TIME: &str = match option_env!("SPK_BUILD_TIME") {
    Some(value) => value,
    None => "unknown",
};
pub const BUILD_COMMIT: &str = match option_env!("SPK_BUILD_COMMIT") {
    Some(value) => value,
    None => "unknown",
};
pub const BUILD_USER: &str = match option_env!("SPK_BUILD_USER") {
    Some(value) => value,
    None => "unknown",
};
pub const BUILD_HOST: &str = match option_env!("SPK_BUILD_HOST") {
    Some(value) => value,
    None => "unknown",
};
pub const BUILD_COMPILER: &str = match option_env!("SPK_BUILD_COMPILER") {
    Some(value) => value,
    None => "rustc",
};

/// Linux `struct new_utsname`, including the NUL terminator in every field.
#[derive(Clone, Copy)]
pub struct UtsName {
    pub sysname: [u8; UTS_FIELD_LEN],
    pub nodename: [u8; UTS_FIELD_LEN],
    pub release: [u8; UTS_FIELD_LEN],
    pub version: [u8; UTS_FIELD_LEN],
    pub machine: [u8; UTS_FIELD_LEN],
    pub domainname: [u8; UTS_FIELD_LEN],
}

impl UtsName {
    const fn empty() -> Self {
        Self {
            sysname: [0; UTS_FIELD_LEN],
            nodename: [0; UTS_FIELD_LEN],
            release: [0; UTS_FIELD_LEN],
            version: [0; UTS_FIELD_LEN],
            machine: [0; UTS_FIELD_LEN],
            domainname: [0; UTS_FIELD_LEN],
        }
    }

    /// Serialize exactly like Linux `struct new_utsname` (six 65-byte fields).
    pub fn to_bytes(self) -> [u8; UTS_FIELD_LEN * 6] {
        let mut bytes = [0; UTS_FIELD_LEN * 6];
        bytes[..UTS_FIELD_LEN].copy_from_slice(&self.sysname);
        bytes[UTS_FIELD_LEN..UTS_FIELD_LEN * 2].copy_from_slice(&self.nodename);
        bytes[UTS_FIELD_LEN * 2..UTS_FIELD_LEN * 3].copy_from_slice(&self.release);
        bytes[UTS_FIELD_LEN * 3..UTS_FIELD_LEN * 4].copy_from_slice(&self.version);
        bytes[UTS_FIELD_LEN * 4..UTS_FIELD_LEN * 5].copy_from_slice(&self.machine);
        bytes[UTS_FIELD_LEN * 5..UTS_FIELD_LEN * 6].copy_from_slice(&self.domainname);
        bytes
    }
}

static NODENAME: SpinLock<[u8; UTS_FIELD_LEN]> = SpinLock::new([0; UTS_FIELD_LEN]);
static DOMAINNAME: SpinLock<[u8; UTS_FIELD_LEN]> = SpinLock::new([0; UTS_FIELD_LEN]);
static UTS_SERIAL: AtomicU64 = AtomicU64::new(0);

fn fixed(text: &str) -> [u8; UTS_FIELD_LEN] {
    let mut field = [0; UTS_FIELD_LEN];
    let length = text.len().min(UTS_NAME_LEN);
    field[..length].copy_from_slice(&text.as_bytes()[..length]);
    field
}

fn text(field: &[u8; UTS_FIELD_LEN]) -> String {
    let length = field
        .iter()
        .position(|&byte| byte == 0)
        .unwrap_or(field.len());
    String::from_utf8_lossy(&field[..length]).into_owned()
}

fn stored_name(lock: &SpinLock<[u8; UTS_FIELD_LEN]>, default: &str) -> String {
    let name = lock.lock();
    if name[0] == 0 {
        String::from(default)
    } else {
        text(&name)
    }
}

fn set_name(lock: &SpinLock<[u8; UTS_FIELD_LEN]>, name: &[u8]) -> Result<(), &'static str> {
    if name.len() > UTS_NAME_LEN {
        return Err("name too long");
    }
    if name.contains(&0) {
        return Err("NUL in name");
    }
    let mut field = [0; UTS_FIELD_LEN];
    field[..name.len()].copy_from_slice(name);
    *lock.lock() = field;
    UTS_SERIAL.fetch_add(1, Ordering::Release);
    Ok(())
}

/// Linux UTS_RELEASE: the kernel release string, distinct from the product name.
pub fn release() -> String {
    format!("{}-spk", VERSION)
}

/// Linux UTS_VERSION: `#<build> SMP <build metadata>`.
pub fn uts_version() -> String {
    format!("#{} SMP {} {}", BUILD_NUMBER, BUILD_TIME, BUILD_COMMIT)
}

pub fn hostname() -> String {
    stored_name(&NODENAME, UTS_DEFAULT_NODENAME)
}

pub fn set_hostname(name: &[u8]) -> Result<(), &'static str> {
    set_name(&NODENAME, name)
}

pub fn domainname() -> String {
    stored_name(&DOMAINNAME, UTS_DOMAINNAME)
}

pub fn set_domainname(name: &[u8]) -> Result<(), &'static str> {
    set_name(&DOMAINNAME, name)
}

pub fn uts_serial() -> u64 {
    UTS_SERIAL.load(Ordering::Acquire)
}

/// Snapshot of the UTS namespace in the Linux `struct new_utsname` layout.
pub fn utsname() -> UtsName {
    UtsName {
        sysname: fixed(UTS_SYSNAME),
        nodename: fixed(&hostname()),
        release: fixed(&release()),
        version: fixed(&uts_version()),
        machine: fixed(UTS_MACHINE),
        domainname: fixed(&domainname()),
    }
}

/// SpaceOS product banner used at boot; the UTS view remains Linux-compatible.
pub fn banner() -> String {
    format!(
        "{} {} #{} SMP {} {} ({})",
        NAME, VERSION, BUILD_NUMBER, BUILD_TIME, BUILD_COMMIT, UTS_MACHINE
    )
}

/// Linux `/proc/version` format with SpaceKernel identity:
/// `<sysname> version <release> (<user>@<host>) (<compiler>) <UTS_VERSION>`.
pub fn version_line() -> String {
    format!(
        "{} version {} ({}@{}) ({}) {}\n",
        UTS_SYSNAME,
        release(),
        BUILD_USER,
        BUILD_HOST,
        BUILD_COMPILER,
        uts_version()
    )
}
